function poseLimb(limb,offset){
  screenPoint(
    sampled[offset],sampled[offset+1],
    sampled[offset+4],limb.palm
  );
  screenPoint(
    sampled[offset+2],sampled[offset+3],
    sampled[offset+5],limb.elbow
  );
  warpPoint(limb.restShoulder,limb.shoulder);

  const width=sampled[offset+6];
  setSegment(limb.upper,limb.shoulder,limb.elbow,1.06,1.03);
  setSegment(
    limb.forearm,limb.elbow,limb.palm,width,1+(width-1)*.5
  );

