    sampled[offset+11],sampled[offset+10],sampled[offset+9]
  );
  const palmWidth=sampled[offset+7];
  limb.hand.scale.set(
    palmWidth,
    sampled[offset+8],
    1+(palmWidth-1)*.35
  );
}

function render(t){
  const numericTime=Number(t);
  const time=Number.isFinite(numericTime)
    ?((numericTime%period)+period)%period:0;
  sample(time);
  poseBody();
